const fixedPngBase64 = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==';
const fixedJpegBase64 = '';

export function fixedQrPng(): Buffer {
  const bytes = Buffer.from(fixedPngBase64, 'base64');
  if (bytes.subarray(0, 8).toString('hex') !== '89504e470d0a1a0a') throw new Error('fixed PNG fixture has an invalid signature');
  return bytes;
}

export function fixedQrJpeg(): Buffer {
  const bytes = Buffer.from(fixedJpegBase64, 'base64');
  if (bytes[0] !== 0xff || bytes[1] !== 0xd8 || bytes[2] !== 0xff) throw new Error('fixed JPEG fixture has an invalid signature');
  return bytes;
}
